def dump_config_snapshot(self, path: str) -> None:
    """Write the full current runtime configuration to a JSON file at the given path."""
    try:
        directory = os.path.dirname(path)
        if directory:
            os.makedirs(directory, exist_ok=True)
        with open(path, 'w') as f:
            json.dump(self.config_data, f, indent=2, sort_keys=True)
        logger.info(f"Config snapshot written to {path}")
    except Exception as e:
        logger.warning(f"Failed to write config snapshot to {path}: {e}")

